def _follow_document_scope(core: SyncClientCore, ids: Mapping[str, Any]) -> Follow[Document]:
    """How `caitlyn.knowledge_bases(knowledge_base_id).documents(document_id)` follows its thing through WatchKnowledgeBase."""
    watched = Watched(_operations.WATCH_KNOWLEDGE_BASE, {"knowledge_base_id": ids["knowledgeBaseId"], "document": ids["documentId"]}, _operations.WATCH_KNOWLEDGE_BASE_EVENTS, "document", str(ids["documentId"]))
    return Follow(core, watched, _operations.CODE_ERRORS, DocumentScope(core, ids).get)


