class IngestionSyncMethod:
    """`caitlyn.knowledge_bases(knowledge_base_id).ingestion.sync`: keep the knowledge base in step with a folder of files, or a list of files; `.estimate(…)` with
    the same arguments plans it and says what it would cost, uploading nothing.
    """

    def __init__(self, core: SyncClientCore, ids: Mapping[str, Any]) -> None:
        self._core = core
        self._ids: dict[str, Any] = dict(ids)

    def __call__(
        self,
        source: str | PathLike[str] | Sequence[SyncFile],
        *,
        folder: str = "/",
        policy: IngestionPolicy | None = None,
        include: Sequence[str] = (),
        exclude: Sequence[str] = (),
        key: Callable[[SyncFile], str | None] | None = None,
        source_url: Callable[[SyncFile], str | None] | None = None,
        metadata: Callable[[SyncFile], Mapping[str, object] | None] | None = None,
        remove_missing: bool = False,
        upload_window_seconds: int | None = None,
        confirm: Callable[[SyncPlan[IngestionBatch, IngestionBatchItem, EstimateIngestionResult]], bool] | None = None,
        resolver: Callable[[list[IngestionBatchItem]], Mapping[str, str]] | None = None,
        on_progress: Callable[[IngestionProgress[IngestionBatchItem]], object] | None = None,
        on_item: Callable[[IngestionBatchItem], object] | None = None,
        concurrency: int = 6,
        cancel_ingestion: bool = False,
    ) -> SyncReport[IngestionBatch, IngestionBatchItem]:
        """Keeps the knowledge base in step with a folder of files, or a list of files, through one ingestion batch.

        In order: hashes each file; creates the batch to start by hand (10,000 items a call); waits until it is planned and
        prices it; resolves it; starts it; uploads each file that needs its bytes under the batch's upload policy, at most
        `concurrency` at once, and reports them; waits until the batch finishes; and returns a report of every item.

        Args:
            source: a folder (walked without following symbolic links, filtered by `include`, `exclude` and each
                folder's `.caitlynignore`), or a list of `SyncFile`.
            folder: the knowledge base folder the files' relative paths are under (default `/`).
            policy: the rules that resolve each item's outcome (`IngestionPolicy`).
            key: a function of each file giving its item's `externalId`; by default its relative path.
            source_url, metadata: functions of each file giving its item's `sourceUrl` and `metadata`.
            remove_missing: also remove each document under `folder` that no file names.
            upload_window_seconds: how long the batch waits for its files once it starts, in seconds: each upload policy
                lasts this long. The server's default (30 minutes) when not given.
            confirm: called with the plan and its estimate before anything is uploaded; returning False cancels the batch
                and raises CaitlynError with code CANCELLED (status 0) and the report so far as its report.
            resolver: called with the items the policy left `unresolved`; returns a resolution (`add`,
                `new_version`, `overwrite`, `skip`…) for each item id. Without one, unresolved items raise
                `INGESTION_BATCH_UNRESOLVED` and the batch is left planned.
            on_progress: called with each `IngestionProgress` (`checksum`, `planning`, `planned`, `upload` in bytes,
                `queued`, `processing`, then the batch's final status).
            on_item: called with each item once it is final.
            concurrency: uploads at once (default 6).
            cancel_ingestion: when the call is cancelled, also cancel the batch, stopping ingestion already running.

        An item whose upload fails is reported failed (`UPLOAD_FAILED`) and never raised; an error that stops the whole batch
        is raised with the batch's own failure code.

        Cancellation is KeyboardInterrupt (Ctrl-C): it drops the uploads in flight, starts no new ones, and raises
        `SyncInterrupted`, a `KeyboardInterrupt` whose `report` is the report so far.
        """
        return run_sync(lambda: sync_async(
            SyncHelperCore(self._core), _operations.SYNC_API, IngestionBatch, IngestionBatchItem, EstimateIngestionResult,
            self._ids["knowledgeBaseId"],
            source,
            folder=folder,
            policy=policy,
            include=include,
            exclude=exclude,
            key=key,
            source_url=source_url,
            metadata=metadata,
            remove_missing=remove_missing,
            upload_window_seconds=upload_window_seconds,
            confirm=confirm,
            resolver=resolver,
            on_progress=on_progress,
            on_item=on_item,
            concurrency=concurrency,
            cancel_ingestion=cancel_ingestion,
        ))

    def estimate(
        self,
        source: str | PathLike[str] | Sequence[SyncFile],
        *,
        folder: str = "/",
        policy: IngestionPolicy | None = None,
        include: Sequence[str] = (),
        exclude: Sequence[str] = (),
        key: Callable[[SyncFile], str | None] | None = None,
        source_url: Callable[[SyncFile], str | None] | None = None,
        metadata: Callable[[SyncFile], Mapping[str, object] | None] | None = None,
        remove_missing: bool = False,
        upload_window_seconds: int | None = None,
    ) -> SyncPlan[IngestionBatch, IngestionBatchItem, EstimateIngestionResult]:
        """What `sync` with the same arguments would do and cost: steps 1 to 3 (hash, create the batch, wait until it is planned)
        and the price of the items that need bytes. Uploads nothing; the batch is left planned: its plan goes stale after 5 minutes (starting it plans it again), and a batch never started is cleared after 7 days.
        """
        return run_sync(lambda: sync_estimate_async(
            SyncHelperCore(self._core), _operations.SYNC_API, IngestionBatch, IngestionBatchItem, EstimateIngestionResult,
            self._ids["knowledgeBaseId"],
            source,
            folder=folder,
            policy=policy,
            include=include,
            exclude=exclude,
            key=key,
            source_url=source_url,
            metadata=metadata,
            remove_missing=remove_missing,
            upload_window_seconds=upload_window_seconds,
        ))


