class BatchUploadMethod:
    """`caitlyn.knowledge_bases(knowledge_base_id).ingestion.batches(ingestion_batch_id).upload(files)`: sends the files of the batch's items awaiting upload; `.estimate(files)` says what
    uploading them would take and cost, before the batch is started.
    """

    def __init__(self, core: SyncClientCore, ids: Mapping[str, Any]) -> None:
        self._core = core
        self._ids: dict[str, Any] = dict(ids)

    def __call__(
        self,
        files: BatchFiles[IngestionBatchItem],
        *,
        concurrency: int = 6,
        on_progress: Callable[[IngestionProgress[IngestionBatchItem]], object] | None = None,
        on_item: Callable[[IngestionBatchItem], object] | None = None,
    ) -> Started[BatchUpload[IngestionBatch, IngestionBatchItem], IngestionBatch]:
        """Sends the files of the batch's items awaiting upload, as `ingestion.sync` does, and reports them.

        Start the batch first (`batch.start()`); a batch created with `start="when_planned"` that is still planning is
        followed until it runs. Otherwise a batch not started raises `INGESTION_BATCH_NOT_STARTED` (status 0), with nothing sent.

        Args:
            files: each item's file, by the item's path as the batch stores it (`/hr/leave.pdf`; a key without its
                leading `/` matches too), or a function from an item to its file (or None for none).
            concurrency: uploads at once (default 6).
            on_progress: called with each `IngestionProgress`: `upload` in bytes, with the item, then `queued`, items
                accepted of items uploaded.
            on_item: called with each item that fails during this call (`UPLOAD_FAILED`, `FILE_CHANGED`, or a second
                `CHECKSUM_MISMATCH`). Accepted items end later, during ingestion: `wait()` and `watch()` report them.

        Files are not hashed: a file whose size is not its item's fails that item with `FILE_CHANGED` before it is
        sent, and storage refuses other bytes of the right size against the item's checksum (`FILE_CHANGED` too). One
        item's failure is that item's alone. An awaiting item with no file given is left awaiting upload, in `not_given`;
        a given path that matches no awaiting item is in `unmatched`.

        Returns the `BatchUpload` (`batch`, `items`, `not_given`, `unmatched`) as `.result`, with `.wait()`, which
        returns the batch once it has finished, and `.watch()`.

        Cancellation is KeyboardInterrupt (Ctrl-C): it drops the uploads in flight, starts no new ones, and is raised
        again; the batch is left as it is (`batch.cancel()` cancels it).
        """
        out = run_sync(lambda: batch_upload_async(
            SyncHelperCore(self._core), _operations.SYNC_API, IngestionBatch, IngestionBatchItem,
            self._ids["knowledgeBaseId"], self._ids["ingestionBatchId"],
            files,
            concurrency=concurrency,
            on_progress=on_progress,
            on_item=on_item,
        ))
        follow = _follow_batch_scope(self._core, self._ids)
        return Started(out, lambda timeout, on_progress: follow.wait(timeout=timeout, on_progress=on_progress), follow.watch)

    def estimate(
        self,
        files: BatchFiles[IngestionBatchItem] | None = None,
        *,
        timeout: float | None = None,
    ) -> EstimateIngestionResult:
        """What uploading the batch's items that need bytes (`add`, `new_version`, `overwrite`) would take and cost.

        A batch still planning is waited on first (`timeout` in seconds, as `planned()` takes it); a draft batch raises
        `INGESTION_BATCH_NOT_PLANNED` (status 0), with nothing sent. Each item is priced from its file when `files` gives
        one (its name, content type and size, and the `hints` given with it: the file is neither hashed nor read), else
        from the item itself. With nothing to price, the estimate is empty and nothing is sent.
        """
        return run_sync(lambda: batch_upload_estimate_async(
            SyncHelperCore(self._core), _operations.SYNC_API, IngestionBatch, IngestionBatchItem, EstimateIngestionResult,
            self._ids["knowledgeBaseId"], self._ids["ingestionBatchId"],
            files,
            timeout=timeout,
        ))


def _follow_batch_scope(core: SyncClientCore, ids: Mapping[str, Any]) -> Follow[IngestionBatch]:
    """How `caitlyn.knowledge_bases(knowledge_base_id).ingestion.batches(ingestion_batch_id)` follows its thing through WatchKnowledgeBase."""
    watched = Watched(_operations.WATCH_KNOWLEDGE_BASE, {"knowledge_base_id": ids["knowledgeBaseId"], "batch": ids["ingestionBatchId"]}, _operations.WATCH_KNOWLEDGE_BASE_EVENTS, "batch", str(ids["ingestionBatchId"]))
    return Follow(core, watched, _operations.CODE_ERRORS, BatchScope(core, ids).get)


