class UploadsCollection:
    """`caitlyn.core.uploads`: Call it with upload_id for one of them; the calls on the collection are below."""


    def __init__(self, core: SyncClientCore, ids: Mapping[str, Any]) -> None:
        self._core = core
        self._ids: dict[str, Any] = dict(ids)

    def __call__(self, upload_id: str) -> UploadScope:
        """The scope of one: `caitlyn.core.uploads(upload_id)`. Sends nothing."""
        return UploadScope(self._core, {**self._ids, "uploadId": upload_id})

    def reserve(
        self,
        *,
        file_name: str,
        content_type: str,
        byte_size: int,
        sha256: str,
        idempotency_key: str | None = None,
        purpose: UploadPurpose | Mapping[str, object] | None = None,
        expires_in_seconds: int | None = None,
    ) -> CreateUploadResult:
        """Reserves a short-lived slot for a file's bytes and returns a presigned URL bound to their
        checksum.

        Send the bytes with `uploadMethod` to `uploadUrl`, with every header in `requiredHeaders`,
        before `expiresAt`; then pass the upload's `id` to the operation that uses it. Files can be at
        most 2 GB. For an attachment, name the conversation in `purpose`: the conversation's attachment
        settings are checked here, before the bytes travel. The SDKs' `core.uploads.send(file)` does all of
        this, and their document and attachment helpers call it for you. Many files at once go through an
        ingestion batch instead, which signs one upload policy for them all.

        Added in Caitlyn 5.149.0. Stability: beta. `POST /v3/uploads` (CreateUpload).

        Args:
            file_name: The file's name on the caller's machine.
            content_type: The file's media type.
            byte_size: The file's size in bytes, at most 2 GB (2,147,483,648 bytes). A larger file is refused
                with 413 `PAYLOAD_TOO_LARGE`.
            sha256: The base64-encoded SHA-256 of the file's bytes. The upload URL accepts only these bytes.
            idempotency_key: Makes the request safe to retry. The SDKs generate one per call when the caller does not
                supply one.
            purpose: What the upload is for, when that decides whether it is accepted. Absent means a document. Added in Caitlyn 5.149.0.
            expires_in_seconds: How long the upload URL works: from a minute to an hour, and 15 minutes when absent. A short
                lifetime lets a test reach an expired upload within seconds.

                Added in Caitlyn 5.149.0.

        Raises:
            ConflictError: HTTP 409.
            PayloadTooLargeError: HTTP 413.
            UnprocessableContentError: HTTP 422.
            InternalError: HTTP 500.
            PermissionDeniedError: HTTP 403.
            ServiceUnavailableError: HTTP 503.
            TooManyRequestsError: HTTP 429.
            UnauthenticatedError: HTTP 401.
            ValidationError: HTTP 400.
            CaitlynError: any other error response, after retries. A status the operation does not list, but the API models elsewhere, raises that status's class (NotFoundError for 404).
        """
        return self._core.request(
            _operations.CREATE_UPLOAD,
            {"file_name": file_name, "content_type": content_type, "byte_size": byte_size, "sha256": sha256, "idempotency_key": idempotency_key, "purpose": purpose, "expires_in_seconds": expires_in_seconds},
            CreateUploadResult,
        )

    def send(
        self,
        file: FileInput,
        *,
        idempotency_key: str | None = None,
        purpose: UploadPurpose | None = None,
        expires_in_seconds: int | None = None,
    ) -> CreateUploadResult:
        """Uploads a file: hashes it (SHA-256), reserves the upload with `reserve`, then sends the bytes to
        its presigned URL with exactly the headers it names, and returns the upload.

        The PUT carries no Caitlyn credentials and is retried as a call that is safe to repeat. A file over 2 GB fails
        with `FILE_TOO_LARGE` before any request, a path that changes after it was hashed with `FILE_CHANGED`, and a PUT
        that still fails after retries with `UPLOAD_PUT_FAILED`.

        Args:
            file: an `UploadFile` (`from_path`, `from_bytes`, `from_stream`), or a path.
        """
        with self._core.prepare_file(file) as f:
            upload = self.reserve(
                file_name=f.name,
                content_type=f.content_type,
                byte_size=f.byte_size,
                sha256=f.sha256,
                idempotency_key=idempotency_key,
                purpose=purpose,
                expires_in_seconds=expires_in_seconds,
            )
            self._core.put_file(upload.upload_method, upload.upload_url, upload.required_headers, f)
        return upload


