    def __init__(self, core: AsyncClientCore, ids: Mapping[str, Any]) -> None:
        self._core = core
        self._ids: dict[str, Any] = dict(ids)

    def list(
        self,
        *,
        limit: int | None = None,
        cursor: str | None = None,
    ) -> AsyncPaginator[ListConversationsPage, Conversation]:
        """Lists the caller's conversations with one agent, newest first, across its versions.

        Each says which version it is with. Only the caller's own conversations, and those shared with
        it, are listed.

        Added in Caitlyn 5.149.0. Stability: beta. `GET /v3/agents/{agentId}/conversations` (ListConversations).

        Args:
            limit: The most conversations to return, from 1 to 100. Defaults to 20.
            cursor: The `nextCursor` from the previous page. Absent for the first page.

        Raises:
            NotFoundError: HTTP 404.
            InternalError: HTTP 500.
            PermissionDeniedError: HTTP 403.
            ServiceUnavailableError: HTTP 503.
            TooManyRequestsError: HTTP 429.
            UnauthenticatedError: HTTP 401.
            ValidationError: HTTP 400.
            CaitlynError: any other error response, after retries. A status the operation does not list, but the API models elsewhere, raises that status's class (NotFoundError for 404).

        Returns:
            A paginator over every item on every page, from `cursor` (`.pages()` for the pages, `.page()` for one page). Nothing is requested until it is used.
        """
        params: dict[str, object] = {"agent_id": self._ids["agentId"], "limit": limit}

        async def fetch(token: str | None) -> ListConversationsPage:
            return await self._core.request(_operations.LIST_CONVERSATIONS, {**params, "cursor": token}, ListConversationsPage)

        return AsyncPaginator(fetch, lambda page: page.items, lambda page: page.next_cursor, cursor)


