            params,
            _operations.WATCH_WORKSPACE_EVENTS_EVENTS,
            Resume(_operations.WATCH_WORKSPACE_EVENTS, {"types": params["types"], "conversation_ids": params["conversation_ids"], "after": params["after"]}, "last_event_id"),
