            _operations.CREATE_DOCUMENT,
            {"knowledge_base_id": self._ids["knowledgeBaseId"], "upload_id": upload_id, "folder": folder, "source_url": source_url, "external_id": external_id, "metadata": metadata, "extra_metadata": extra_metadata, "idempotency_key": idempotency_key, "name": name},
            CreateDocumentResult,
