def _async_follow_folder_scope(core: AsyncClientCore, ids: Mapping[str, Any]) -> AsyncFollow[Folder]:
    """How `caitlyn.knowledge_bases(knowledge_base_id).folders(folder_path)` follows its thing through WatchKnowledgeBase."""
