    def __call__(self, knowledge_base_id: str, operation_id: str) -> AsyncOperationScope:
        """The scope of one: `caitlyn.core.operations(knowledge_base_id, operation_id)`. Sends nothing."""
        return AsyncOperationScope(self._core, {**self._ids, "knowledgeBaseId": knowledge_base_id, "operationId": operation_id})

    def list(
        self,
        knowledge_base_id: str,
        *,
        limit: int | None = None,
        cursor: str | None = None,
        target_type: Literal["knowledge_base", "folder", "document"] | OperationTargetType | None = None,
        target_id: str | None = None,
        kind: Literal["document_ingestion", "document_update", "folder_change", "permissions_change", "knowledge_base_deletion", "layout_aware_search", "fill_in", "reprocess"] | OperationKind | None = None,
        status: Literal["queued", "running", "succeeded", "completed_with_failures", "failed", "cancelled"] | OperationStatus | None = None,
    ) -> AsyncPaginator[ListOperationsPage, Operation]:
        """Lists the Operations on one knowledge base, or one thing in it, newest first.

        The caller needs read access to the knowledge base. Narrow the list with the target, the kind and
        the status. Rows are filtered to the Operations a direct GetOperation would return for this
        caller: an Operation whose target the caller could not read is left out, not shown with its
        details removed.

        Added in Caitlyn 5.149.0. Stability: beta. `GET /v3/knowledge-bases/{knowledgeBaseId}/operations` (ListOperations).

        Args:
            limit: The most Operations to return, from 1 to 100. Defaults to 20.
            cursor: The `nextCursor` from the previous page. Absent for the first page.
            target_type: Only Operations on this kind of thing.
            target_id: Only Operations on this thing.
            kind: Only Operations of this kind.
            status: Only Operations with this status.

        Raises:
            NotFoundError: HTTP 404.
            InternalError: HTTP 500.
            PermissionDeniedError: HTTP 403.
            ServiceUnavailableError: HTTP 503.
            TooManyRequestsError: HTTP 429.
            UnauthenticatedError: HTTP 401.
            ValidationError: HTTP 400.
            CaitlynError: any other error response, after retries. A status the operation does not list, but the API models elsewhere, raises that status's class (NotFoundError for 404).

        Returns:
            A paginator over every item on every page, from `cursor` (`.pages()` for the pages, `.page()` for one page). Nothing is requested until it is used.
        """
        params: dict[str, object] = {"knowledge_base_id": knowledge_base_id, "limit": limit, "target_type": target_type, "target_id": target_id, "kind": kind, "status": status}

        async def fetch(token: str | None) -> ListOperationsPage:
            return await self._core.request(_operations.LIST_OPERATIONS, {**params, "cursor": token}, ListOperationsPage)

        return AsyncPaginator(fetch, lambda page: page.items, lambda page: page.next_cursor, cursor)


